import{_ as e,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Product Images — Update","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-product-image-update","title":"Update a Product Image","description":"Edit the alt text and the position of an already-uploaded image.","query":"curl -X PUT \\"https://your-domain.com/api/admin/catalog/products/12/images/47\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"alt_text\\": \\"Blue running shoe, side view\\",\\n    \\"position\\": 2\\n  }\'\\n","variables":"{\\n  \\"alt_text\\": \\"Blue running shoe, side view\\",\\n  \\"position\\": 2\\n}\\n","response":"{\\n  \\"id\\": 47,\\n  \\"productId\\": 12,\\n  \\"path\\": \\"product/12/abc123.webp\\",\\n  \\"position\\": 2,\\n  \\"url\\": \\"/storage/product/12/abc123.webp\\",\\n  \\"altText\\": \\"Blue running shoe, side view\\"\\n}\\n","commonErrors":[{"error":"Validation (422)","cause":"Neither an alt text nor a position was sent","solution":"Send at least one of the two fields"},{"error":"Not Found (404)","cause":"The image does not belong to `{productId}`, or the product does not exist","solution":"Verify both ids"}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/images-update.md","filePath":"api/rest-api/admin/catalog/products/images-update.md","lastUpdated":1789385991000}'),r={name:"api/rest-api/admin/catalog/products/images-update.md"};function i(n,t,s,l,c,p){return d(),a("div",null,t[0]||(t[0]=[o('<h1 id="product-images-—-update" tabindex="-1">Product Images — Update <a class="header-anchor" href="#product-images-—-update" aria-label="Permalink to &quot;Product Images — Update&quot;">​</a></h1><p>Edits what is stored alongside an uploaded image: its alt text and its position.</p><p>The file itself is fixed once uploaded — to replace the picture, <a href="/api/rest-api/admin/catalog/products/images-upload.html">upload</a> a new one and <a href="/api/rest-api/admin/catalog/products/images-delete.html">delete</a> this one.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products/{productId}/images/{id}</code></td><td>PUT</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>alt_text</code></td><td>string</td><td>no</td><td>Description of the image, stored for every locale the request covers. Send an empty string to clear it.</td></tr><tr><td><code>position</code></td><td>integer</td><td>no</td><td>Sort position within the product&#39;s gallery.</td></tr></tbody></table><p>At least one of the two is required — a request carrying neither is rejected.</p><h2 id="alt-text-and-locales" tabindex="-1">Alt text and locales <a class="header-anchor" href="#alt-text-and-locales" aria-label="Permalink to &quot;Alt text and locales&quot;">​</a></h2><p>Alt text is translated: it is written for every locale the request covers, and read back for the locale the request is made in. The storefront returns it as <code>altText</code> on the product&#39;s images, and falls back to the product name where an image has none, so an image is never rendered without a description.</p><h2 id="position-and-gallery-order" tabindex="-1">Position and gallery order <a class="header-anchor" href="#position-and-gallery-order" aria-label="Permalink to &quot;Position and gallery order&quot;">​</a></h2><p>Images are returned in position order, so this is what decides which picture is the product&#39;s main image — the lowest position wins, and that is the one the listing and the product card show. To rearrange several at once, use <a href="/api/rest-api/admin/catalog/products/images-reorder.html">reorder</a> instead.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Image id.</td></tr><tr><td><code>productId</code></td><td>integer</td><td>Parent product id.</td></tr><tr><td><code>path</code></td><td>string</td><td>Storage-relative file path.</td></tr><tr><td><code>position</code></td><td>integer</td><td>Sort position.</td></tr><tr><td><code>url</code></td><td>string</td><td>Public URL.</td></tr><tr><td><code>altText</code></td><td>string</td><td>Alt text stored for the current locale, or <code>null</code>.</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid admin Bearer token.</td></tr><tr><td><code>403 Forbidden</code></td><td>Admin role lacks <code>catalog.products.edit</code>.</td></tr><tr><td><code>404 Not Found</code></td><td>Product not found, or the image does not belong to it.</td></tr><tr><td><code>422 Unprocessable Entity</code></td><td>Neither an alt text nor a position was sent.</td></tr></tbody></table>',17)]))}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
